import { useRef, useState } from "react";
import { CameraView, type PermissionResponse } from "expo-camera";
import { Image, Text, View } from "react-native";
import { StyleSheet } from "react-native-unistyles";

import { ActionButton } from "@/ui/action-button";

type PhotoCaptureProps = {
  /** `null` while the current permission status is still being read. */
  permission: PermissionResponse | null;
  photoUri?: string;
  onRequestPermission: () => void;
  onOpenSettings: () => void;
  onCapture: (uri: string) => void;
  onClear: () => void;
};

/**
 * The add-card screen's optional photo. Branches on every camera-permission
 * state — still resolving, granted, deniable, and permanently denied — and
 * only ever asks for the permission when the learner taps "Allow camera
 * access", never on mount.
 */
export function PhotoCapture({
  permission,
  photoUri,
  onRequestPermission,
  onOpenSettings,
  onCapture,
  onClear,
}: PhotoCaptureProps) {
  const cameraRef = useRef<CameraView>(null);
  // The uri of a photo whose `Image` reported it could not load — the OS can
  // reclaim a cached capture between writing it and this screen reading it
  // back. Tracked by value rather than a plain boolean so a freshly captured
  // photo (a new, different uri) is never mistaken for the one that failed.
  const [unavailableUri, setUnavailableUri] = useState<string | undefined>(
    undefined,
  );
  const isUnavailable = photoUri !== undefined && photoUri === unavailableUri;

  async function capture() {
    const photo = await cameraRef.current?.takePictureAsync();
    if (photo?.uri) {
      onCapture(photo.uri);
    }
  }

  if (photoUri && isUnavailable) {
    return (
      <View style={styles.container} testID="photo-unavailable">
        <Text style={styles.hint}>
          This photo is no longer available. Take a new one.
        </Text>
        <ActionButton
          label="Retake photo"
          kind="secondary"
          onPress={onClear}
          testID="retake-photo"
        />
      </View>
    );
  }

  if (photoUri) {
    return (
      <View style={styles.container}>
        <Image
          source={{ uri: photoUri }}
          style={styles.preview}
          testID="photo-preview"
          onError={() => setUnavailableUri(photoUri)}
        />
        <ActionButton
          label="Remove photo"
          kind="secondary"
          onPress={onClear}
          testID="clear-photo"
        />
      </View>
    );
  }

  if (permission === null) {
    return (
      <View style={styles.container} testID="photo-capture-loading">
        <Text style={styles.hint}>Checking camera access…</Text>
      </View>
    );
  }

  if (permission.granted) {
    return (
      <View style={styles.container}>
        <CameraView ref={cameraRef} style={styles.camera} facing="back" />
        <ActionButton
          label="Take photo"
          onPress={capture}
          testID="capture-photo"
        />
      </View>
    );
  }

  if (permission.canAskAgain) {
    return (
      <View style={styles.container}>
        <Text style={styles.hint}>Recall can attach a photo to this card.</Text>
        <ActionButton
          label="Allow camera access"
          onPress={onRequestPermission}
          testID="request-camera-permission"
        />
      </View>
    );
  }

  return (
    <View style={styles.container}>
      <Text style={styles.hint}>
        Camera access is off. Turn it on in system settings to add a photo.
      </Text>
      <ActionButton
        label="Open settings"
        kind="secondary"
        onPress={onOpenSettings}
        testID="open-settings"
      />
    </View>
  );
}

const styles = StyleSheet.create((theme) => ({
  container: {
    gap: theme.spacing(1.5),
  },
  camera: {
    height: theme.sizing.mediaHeight,
    borderRadius: theme.radius.md,
    overflow: "hidden",
  },
  preview: {
    height: theme.sizing.mediaHeight,
    borderRadius: theme.radius.md,
  },
  hint: {
    ...theme.typography.body,
    color: theme.colors.textMuted,
  },
}));

import { StyleSheet } from "react-native-unistyles";

const typography = {
  display: { fontSize: 32, lineHeight: 38, fontWeight: "700" },
  title: { fontSize: 24, lineHeight: 30, fontWeight: "700" },
  heading: { fontSize: 19, lineHeight: 25, fontWeight: "600" },
  body: { fontSize: 16, lineHeight: 24, fontWeight: "400" },
  label: { fontSize: 14, lineHeight: 20, fontWeight: "600" },
  caption: { fontSize: 13, lineHeight: 18, fontWeight: "400" },
} as const;

const radius = {
  sm: 8,
  md: 12,
  lg: 20,
} as const;

const spacing = (steps: number) => steps * 8;

const sizing = {
  /**
   * The height of a full-bleed media surface: the study card's face and the
   * add-card screen's camera preview and photo thumbnail all share it, so a
   * future one has a value to match rather than a new number to invent.
   */
  mediaHeight: 220,
  /**
   * The platform's minimum tappable dimension: every pressable control's
   * minimum width and/or height references this rather than a new literal,
   * the same way `mediaHeight` above is shared rather than repeated.
   */
  minTouchTarget: 44,
} as const;

const shared = {
  typography,
  radius,
  spacing,
  sizing,
} as const;

const light = {
  ...shared,
  colors: {
    background: "#f7f8fa",
    surface: "#ffffff",
    text: "#1b1f24",
    textMuted: "#5a6472",
    accent: "#3a49c9",
    onAccent: "#ffffff",
    positive: "#1f7a4d",
    negative: "#b3271e",
    border: "#767e8a",
    focusRing: "#3a49c9",
  },
} as const;

const dark = {
  ...shared,
  colors: {
    background: "#0f1216",
    surface: "#171b21",
    text: "#e8ecf1",
    textMuted: "#9aa5b4",
    accent: "#9fb0ff",
    onAccent: "#0f1216",
    positive: "#63d19a",
    negative: "#ff9a92",
    border: "#6c7684",
    focusRing: "#9fb0ff",
  },
} as const;

const themes = { light, dark };

type AppThemes = typeof themes;

declare module "react-native-unistyles" {
  // Interface merging is how Unistyles' own types pick up this app's theme
  // shape; an empty body is expected here, not a mistake.
  // eslint-disable-next-line @typescript-eslint/no-empty-object-type
  export interface UnistylesThemes extends AppThemes {}
}

StyleSheet.configure({
  settings: { adaptiveThemes: true },
  themes,
});

